INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest333-geol102', 'stk-guest333', 'GEOL 102', 'doc', '{"docs": [{"id": "stk-dr-f104251", "n": "Dr. Michael Anthony Kaminski", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Geol102\n\nالتحضير : متساهل لأبعد ومو هو الي يحضر مساعده يكون متواجد ويعطي ورقة تمر على الطلاب بمجرد تحط صح انت حاضر\n\nطريقة الشرح : مملة وصعب تركز معاه والدكتور كبير بالعمر وصوته ضعيف، الدكتور له خبرة كبيرة بالمجال وممكن يعطي ولو حاولت أركز معاه ممكن فهمت شوي عليه ولكن المادة اشوفها ثقيلة مو معه بس ولكن بشكل عام. ممكن يجيب قصة وتجيكم سؤال بونص.\n\nالكويزات : 8 اسئلة MCQ + سؤالين فراغ وسؤال مقالي بونص ومختلفة الطول طبيعي تلاقي خيار فيه سطرين. يركز على الجداول والرسومات والصور اكثر من النصوص الكثيرة\n\nالمياجر: 3 مياجر وكانت صعبة ويجيب فيه امور غير عن الكويز مرة ويركز على الامثلة الواقعية يعني ما بجيبلك النوع الفلاني من Faults بوش يتميز؟ بقولك Faults الي في المدينة الفلانية بوش يتميز. وقليل يجيبون 25/27 هو يعني 27 مع البونص وبدونه الفل 25\n\nالفاينلات : لا يوجد\n\nالقريد النهائي: B\n\nالصوت: ضعيف والدكتور الاكسنت حقه أمريكي لكنه الظاهر بولندي\n\nإضافات : الدكتور طيب ومروق ووسيع صدر مرات يرمي نكات نيردز عشان يمون مع الدوافير. التصحيح وشغل البلاك بورد والتحضير على المساعدين الاثنين وأيضا كانوا متساعدين وواحد منهم هو الي يصحح الكويزات والمياجر واشوف ان تصحيحه عسل. في الكورس يكون فيه Field trip حول بعض من الجامعة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1540985-geol102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-michael-anthony-kaminski/104251/11", "user": "guest333", "ts": 1770419576852, "tid": 104251, "pn": 11}}]}', 1770419576852, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fms1-geol102', 'stk-fms1', 'GEOL 102', 'doc', '{"docs": [{"id": "stk-dr-f176834", "n": "Dr. John Humphrey", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "GEOL102-T202\n\nالتحضير: المحاضرات يسويها عن طريق زوم و يحضر من البرنامج نفسه اتوماتيكيا. يحضر المتاخر بعد بس الماده عليها 6 درجات حضور و على كل غياب ينقص 0.5.\n\nالكويزات: مفروض تكون كوزين كل واحد عليه 5% الاول يكون عن الجدول الزمني و كان سهل. الكويز الثاني بدله لنا و عطانا واجب نكتب 3 برقرافات عن بركانين صارو قبل فترة قريبه و نقارن بينهم. كان الافرج حق الواجب 3.25/5.\n\nالمياجر و الفاينل: الماده فيها 3 مياجر و الفاينل مضمون معهم كل واحد عليه 28% و الحلو فيه انه اذ اختبرت الميجر خلاص الاشياء الي اختبرتها ما بتجي بعدين مو كمبرهنسف. و صعوبة المياجر اعطيها متوسط الى صعب شوي لبعض الاسئلة. بالميجر الثاني سالنا عن زلزال صاير قبل اسبوعين صاير بنيوزلندا و سال عن اسمه فا الي مركز بالشرح بيسمع الدكتور يتكلم عنه و يعرف+ لازم تكتب نوتات معه عشان تجيب درجة كويسه ما ينفع بس سلايدات لان الدكتور يسوي الي يبي و يجيب اسئلة شاطحه عن المنهج لكن يكون متكلم عنها بالكلاس.\n\nالقريد: الافرج حق الكلاس كان 78.94% و سوال له كيرف الى 84% زادنا 5.06% و ذا الشي يسويه كل ترم انه يسوي كيرف الى B or B+. و ذا توزيع الدرجات حق الكلاس\nA+ = 7, A = 5, B+ = 5, B = 6, C+ = 6, C = 4, D+ = 2, D = 1, F = 1\n\nالصوت: واضح لكنه مرات يتكلم بسرعه فا بعض الشباب ما يلحقون على كلامه لكن اشوف كويس انا. و اذ ما فهمت عليه فهو ينزل الريكوردنق ببلاك بورد فا يمديك تراجع.\n\nالدكتور حبوب و يحب ياخذ و يعطي بس ما يحب تجادله مثال: اذ قلت له ياجل كويز بيقول انك طالب بترول و و و و. + يوم عطانا الواجب بعض الطلاب كلموه و فصل بعد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529887-geol102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/john-humphrey/176834/5", "user": "FMS1", "ts": 1620379515000, "tid": 176834, "pn": 5}}]}', 1620379515000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
